  public Vector2 offsetMin {get=>new Vector2(anchoredPosition.x-sizeDelta.x*pivot.x,anchoredPosition.y-sizeDelta.y*pivot.y);set{var delta=value-offsetMin;sizeDelta=sizeDelta-delta;anchoredPosition=anchoredPosition+new Vector2(delta.x*(1-pivot.x),delta.y*(1-pivot.y));}}
